```sql
/* Подсчёт атомов в молекулах, помеченных как канцерогенные (label = '+') и содержащих атомы водорода (element = 'h') */
SELECT COUNT(a."atom_id") AS atom_count
FROM "molecule" m
JOIN "atom" a ON a."molecule_id" = m."molecule_id"
WHERE m."label" = '+'
  AND m."molecule_id" IN (
      /* Молекулы, содержащие хотя бы один атом водорода */
      SELECT a2."molecule_id"
      FROM "atom" a2
      WHERE LOWER(a2."element") = 'h'
  );
```

```sql
/* Подсчёт общего числа атомов в молекулах, содержащих тройную связь и атомы фосфора или брома */
SELECT COUNT(DISTINCT a."atom_id") AS total_atoms
FROM "atom" a
JOIN "molecule" m ON a."molecule_id" = m."molecule_id"
WHERE a."molecule_id" IN (
    /* Молекулы с тройной связью */
    SELECT b."molecule_id"
    FROM "bond" b
    WHERE b."bond_type" = '#'
)
AND a."molecule_id" IN (
    /* Молекулы, содержащие фосфор или бром */
    SELECT a2."molecule_id"
    FROM "atom" a2
    WHERE LOWER(a2."element") IN ('p', 'br')
);
```

```sql
/* Выбираем молекулы, у которых есть одинарные связи (bond_type = '-') */
/* и которые не являются канцерогенными (label = '-') */
/* Возвращаем топ-3 уникальных molecule_id в алфавитном порядке */
SELECT DISTINCT m."molecule_id"
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
WHERE m."label" = '-'
  AND b."bond_type" = '-'
ORDER BY m."molecule_id"
LIMIT 3;
```

```sql
/* Вычисляем процент молекул, содержащих водород (element = 'h'), среди канцерогенных молекул (label = '+') */
SELECT
    /* Доля молекул с водородом среди канцерогенных, умноженная на 100 */
    SUM(CASE WHEN LOWER(a."element") = 'h' THEN 1 ELSE 0 END) * 100.0
    / COUNT(DISTINCT m."molecule_id") AS percentage
FROM "molecule" m
/* Соединяем молекулы с атомами */
JOIN "atom" a
    ON a."molecule_id" = m."molecule_id"
/* Ограничиваем выборку канцерогенными молекулами */
WHERE m."label" = '+';
```

