```sql
/* Вычисляем процент карциногенных молекул среди связей типа '#' (тройные связи) */
SELECT
    /* Процент = (число тройных связей у карциногенных молекул * 100) / общее число связей у карциногенных молекул */
    (SUM(CASE WHEN b."bond_type" = '#' THEN 1 ELSE 0 END) * 100.0) / COUNT(b."bond_id") AS percent
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
WHERE m."label" = '+';
```

```sql
/* Процент японских переводов среди наборов типа expansion */
SELECT
    /* Доля наборов типа expansion среди японских переводов, в процентах */
    (COUNT(*) FILTER (WHERE s."type" = 'expansion')::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS percentage
FROM set_translations st
JOIN sets s ON s."code" = st."setcode"
WHERE st."language" = 'Japanese';
```

```sql
/* Доля карт Story Spotlight без текстового блока (istextless = 0) от общего числа карт */
SELECT
    /* Процент: карты Story Spotlight без текста / все карты * 100 */
    (COUNT(*) FILTER (WHERE "isstoryspotlight" = 1 AND "istextless" = 0)::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS percentage,
    /* Список ID таких карт */
    ARRAY_AGG("id") FILTER (WHERE "isstoryspotlight" = 1 AND "istextless" = 0) AS story_spotlight_textless_ids
FROM "cards";
```

