/* Соотношение между супергероями мужского и женского пола */
SELECT
    /* Количество мужских супергероев */
    SUM(CASE WHEN g."gender" = 'Male' THEN 1 ELSE 0 END)::numeric
    /
    /* Количество женских супергероев */
    NULLIF(SUM(CASE WHEN g."gender" = 'Female' THEN 1 ELSE 0 END), 0) AS ratio
FROM "superhero" s
JOIN "gender" g ON s."gender_id" = g."id";
```

